gameActivityClassAdditions.insert:
// MobileNativeCode Plugin - WebView Helper
public void AndroidThunkJava_OpenWebView(String url)
{
	WebViewHelper.Initialize(this);
	WebViewHelper.OpenWebView(url);
}

public void AndroidThunkJava_CloseWebView()
{
	WebViewHelper.CloseWebView();
}

public boolean AndroidThunkJava_IsWebViewOpen()
{
	return WebViewHelper.IsWebViewOpen();
}

// MobileNativeCode Plugin - StashPay Helper
public void AndroidThunkJava_OpenStashPayCheckout(String url)
{
	StashPayHelper.Initialize(this);
	StashPayHelper.OpenCheckout(url);
}

public void AndroidThunkJava_DismissStashPayCheckout()
{
	StashPayHelper.DismissCheckout();
}

public boolean AndroidThunkJava_IsStashPayCheckoutOpen()
{
	return StashPayHelper.IsCheckoutOpen();
}

// Called from Java when payment succeeds
public void AndroidThunkJava_NotifyPaymentSuccess(String itemName)
{
	// This will be implemented to call C++ via JNI
	nativeNotifyPaymentSuccess(itemName);
}

// Native method declaration
private native void nativeNotifyPaymentSuccess(String itemName);
